<?php
declare(strict_types=1);session_start();
spl_autoload_register(function(string $class):void{$prefix='MyGame\\';if(!str_starts_with($class,$prefix))return;$p=__DIR__.'/../src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($p))require$p;});
use MyGame\Infrastructure\Database\Connection;use MyGame\Infrastructure\Company\DatabaseCompanyRepository;
$error=null;$_SESSION['company_csrf']??=bin2hex(random_bytes(24));$csrf=$_SESSION['company_csrf'];$repo=new DatabaseCompanyRepository(Connection::make());
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Neteisinga užklausa.');$id=$repo->create((string)$_POST['name'],(string)$_POST['city'],(string)$_POST['industry'],(float)str_replace(',','.',(string)$_POST['capital']));$_SESSION['company_id']=$id;header('Location: state.php');exit;}catch(Throwable$e){$error=$e->getMessage();}}
?><!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYGAME – steigimas</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="topbar"><div><b>MYGAME</b><span>Verslo simuliatorius</span></div></div><main class="page"><div class="intro"><span class="eyebrow">NAUJAS VERSLAS</span><h1>Įsteigti įmonę</h1><p>Nuo šios įmonės prasidės jūsų ekonomikos istorija.</p></div><?php if($error):?><div class="loan-alert bad"><?=htmlspecialchars($error)?></div><?php endif;?><section class="card setup-card"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><label>Įmonės pavadinimas<input name="name" required></label><label>Miestas<select name="city"><option>Vilnius</option><option>Kaunas</option><option>Klaipėda</option><option>Šiauliai</option><option>Panevėžys</option></select></label><label>Veikla<select name="industry"><option value="retail">Prekyba</option><option value="logistics">Logistika</option><option value="manufacturing">Gamyba</option><option value="services">Paslaugos</option></select></label><label>Pradinis kapitalas<input name="capital" inputmode="decimal" value="25000"></label><button class="start">Įsteigti įmonę →</button></form></section></main></body></html>